const E=Expense,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const embedded=new URLSearchParams(location.search).get('embed')==='1',STORAGE=embedded?'bevy-hr-expenses-v3':'bevy-expenses-v1';let hostContext=null;let s;try{s=E.migrate(JSON.parse(localStorage.getItem(STORAGE)))}catch{s=E.demoSeed()}s.syncSettings||={mode:'Demo',spreadsheetId:'',ledgerTab:'Expense_Ledger',summaryTab:'Payout_Summary',lastError:''};if(!embedded){for(const name of ['HR reviewer','Super Admin reviewer'])if(!s.employees.some(e=>e.name===name))s.employees.push({name,id:'DEMO-'+name.replace(/ /g,'-'),email:name.toLowerCase().replace(/ /g,'.')+'@bevycommerce.com',canReview:true});}if(!embedded){const known=E.seed().employees;for(const e of s.employees){const match=known.find(x=>x.id===e.id&&x.name===e.name);if(!e.email&&match)e.email=match.email;if(!e.email&&['HR reviewer','Super Admin reviewer'].includes(e.name)&&e.id==='DEMO-'+e.name.replace(/ /g,'-'))e.email=e.name.toLowerCase().replace(/ /g,'.')+'@bevycommerce.com';}}let page='Overview',search='',filter='All';const pages=['Overview','My expenses','Review queue','Payouts','Payroll sync','Controls & tests'];const icons=['◫','↗','✓','▤','▦','⚙'];const role=()=>hostContext?.role||$('#role').value,person=()=>hostContext?.employee||$('#person').value,admin=()=>['HR','Super Admin'].includes(role()),actor=()=>hostContext?.employee||(admin()?role()+' reviewer':person());const cad=n=>'CA$'+Number(n||0).toFixed(2),orig=c=>`${c.currency} ${Number(c.amount).toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2})}`,value=c=>c.lockedCAD??E.round((c.approved??c.amount)*s.rates[c.currency]),visible=()=>s.claims.filter(c=>role()!=='Employee'||c.employee===person());
function save(){localStorage.setItem(STORAGE,JSON.stringify(s));render()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.to);window.to=setTimeout(()=>$('#toast').style.display='none',5500)}function act(fn){try{fn();save()}catch(e){toast(e.message)}}function go(p){page=p;search='';filter='All';render()}function head(title,sub,button=''){return `<div class="pagehead"><div><div class="eyebrow">PEOPLE OPERATIONS</div><h1>${title}</h1><div class="sub">${sub}</div></div>${button}</div>`}function pill(st){return `<span class="pill ${esc(st)}">${esc(st)}</span>`}function modal(html){$('#modal').innerHTML=`<button class="close" onclick="closeModal()" aria-label="Close">×</button>${html}`;$('#modal').showModal()}function closeModal(){$('#modal').close()}
function rows(cs){return cs.length?`<div class="scroll"><table><thead><tr><th>EXPENSE / EMPLOYEE</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><strong>${esc(c.vendor)}</strong><small>${esc(c.category)} · ${esc(c.employee)}</small>${c.flag?'<small style="color:#a17830">⚑ Review flag</small>':''}</td><td>${esc(c.date)}<small>${esc(c.id)}</small></td><td><strong>${esc(orig(c))}</strong><small>${cad(value(c))} ${c.lockedCAD!=null?'locked':'estimate'}</small></td><td>${pill(c.status)}<small>${esc(c.stage==='Manager'?'Colleague review':c.stage==='HR'?'HR final review':c.stage==='Information'?'Claimant response needed':'')}</small></td><td><button class="link" onclick="detail('${c.id}')">View ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No expenses here. You’re all caught up.</div>'}
function overview(){const cs=visible(),unpaid=cs.filter(c=>c.status==='Approved'),review=cs.filter(c=>['Submitted','Needs Information'].includes(c.status)),paid=cs.filter(c=>c.status==='Paid'),reserved=cs.filter(c=>['Reserved','Synced'].includes(c.status));return head('Expenses, without the guesswork.','A clear view of every claim, approval and reimbursement.','<button class="primary" onclick="newClaim()">＋ Submit expense</button>')+`<div class="stats"><div class="stat featured"><small>APPROVED & UNPAID</small><strong>${cad(unpaid.reduce((a,c)=>a+value(c),0))}</strong><em>${unpaid.length} expenses ready for a payout</em></div><div class="stat"><small>AWAITING REVIEW</small><strong>${review.length.toString().padStart(2,'0')}</strong><em>Submitted or needs information</em></div><div class="stat"><small>RESERVED FOR PAYOUT</small><strong>${cad(reserved.reduce((a,c)=>a+value(c),0))}</strong><em>${reserved.length} claims safely assigned</em></div><div class="stat"><small>REIMBURSED</small><strong>${cad(paid.reduce((a,c)=>a+value(c),0))}</strong><em>Paid history · never counted twice</em></div></div><div class="grid"><div><div class="notice"><strong>HR review. Clear decisions. One payout.</strong><br>Only HR-approved, unpaid claims enter a batch. Salary dates can move; paid claims stay out of the next payout.</div><section class="card"><div class="cardhead"><div><h2>Recent expenses</h2><span class="sub">Original currency stays with every claim.</span></div><button class="link" onclick="go('My expenses')">View all →</button></div>${rows(cs.slice().reverse().slice(0,6))}</section><div class="card"><div class="cardbody"><h3>Your next move</h3><div class="flex">${admin()?`<button onclick="go('Review queue')">Review claims →</button>`:`<button onclick="go('My expenses')">Track my expenses →</button>`}${admin()?'<button onclick="go(\'Payouts\')">Prepare a payout →</button><button onclick="go(\'Controls & tests\')">Prove the safeguards →</button>':''}</div></div></div></div><div><div class="card"><div class="cardbody"><div class="eyebrow">A SIMPLER WORKFLOW</div><h2>From receipt to reimbursed.</h2>${[['Submit','Add the amount, purpose and receipt.'],['Review','HR or Super Admin validates the bill and approved amount.'],['Pay','HR locks the batch and confirms payment.']].map((x,i)=>`<div class="step"><span class="num">${i+1}</span><div><strong>${x[0]}</strong><p>${x[1]}</p></div></div>`).join('')}<div class="ratebox"><strong>CAD conversion</strong><br>${esc(s.source)}<br>Rate snapshot: ${esc(new Date(s.rateTime).toLocaleString())}<br>Unpaid = estimate. Released = locked.</div></div></div><div class="card"><div class="cardbody"><h3>Salary stays separate.</h3><p class="sub">This workspace handles reimbursements only. No base salaries, salary totals or payroll formulas are stored here.</p></div></div></div></div>`}
function inbox(){return s.claims.filter(c=>admin()?['Submitted','Awaiting HR','Needs Information'].includes(c.status):E.canReview(c,role(),actor())&&['Submitted','Awaiting HR'].includes(c.status));}
function claimsView(review=false){let cs=review?inbox():visible();cs=cs.filter(c=>(filter==='All'||c.status===filter)&&[c.vendor,c.employee,c.id,c.category].join(' ').toLowerCase().includes(search.toLowerCase()));return head(review?'Approval inbox':'My expenses',review?'Every submission arrives here. HR or Super Admin approves, rejects or requests information.':'Every receipt, original amount and payment status in one place.',review?'':'<button class="primary" onclick="newClaim()">＋ Submit expense</button>')+(review&&role()==='Employee'?'<div class="notice">Your employee account includes an approval inbox. Only HR and Super Admin validate expenses.</div>':'')+`<section class="card"><div class="cardhead"><h2>${review?(admin()?'All incoming requests':'Requests assigned to me'):'Expense history'}</h2><span class="sub">${cs.length} claims</span></div><div class="toolbar"><input aria-label="Search expenses" placeholder="Search employee, vendor or claim ID…" value="${esc(search)}" oninput="search=this.value;refreshRows(${review})"><select aria-label="Filter status" onchange="filter=this.value;render()">${['All','Submitted','Awaiting HR','Needs Information','Approved','Reserved','Synced','Paid','Rejected'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select></div><div id="claimRows">${rows(cs)}</div></section>`}
function refreshRows(review){const cs=(review?inbox():visible()).filter(c=>(filter==='All'||c.status===filter)&&[c.vendor,c.employee,c.id,c.category].join(' ').toLowerCase().includes(search.toLowerCase()));$('#claimRows').innerHTML=rows(cs)}
let formOriginal=null;
function newClaim(existing){const c=existing||{},owner=c.id?c.employee:(hostContext?.employee||(admin()?actor():person()));if(c.id&&!admin()&&c.employee!==person()){toast('Only the claimant or HR can edit this expense.');return;}formOriginal=c;const ownerId=c.id?(c.employeeId||''):(s.employees.filter(e=>e.name===owner).length===1?s.employees.find(e=>e.name===owner).id:'');modal(`<h2>${c.id?'Update expense':'Submit a work expense'}</h2><p class="sub">Add the bill, amount and purpose. The form asks only what this category needs.</p><form id="claimForm"><div class="formgrid"><div class="field">Employee<strong>${esc(owner)}</strong><input name="employeeId" type="hidden" value="${esc(ownerId)}"><input name="employee" type="hidden" value="${esc(owner)}"></div><label class="field">Expense category<select name="category" onchange="categoryFields();preview()">${Object.keys(s.rules).map(n=>`<option ${n===c.category?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field">Expense date<input required type="date" name="date" max="${E.businessDate()}" value="${c.date||E.businessDate()}"></label><label class="field">Vendor / service<input required name="vendor" value="${esc(c.vendor||'')}" placeholder="Who issued the bill?"></label><label class="field">Total amount<input required type="number" name="amount" min="0.01" step="0.01" value="${c.amount||''}" oninput="preview()"></label><label class="field">Currency<select name="currency" onchange="preview()">${Object.keys(s.rates).map(n=>`<option ${n===(c.currency||'BDT')?'selected':''}>${n}</option>`).join('')}</select></label><div id="categoryFields" class="full dynamic-fields"></div><label class="field full">Work purpose<input required name="purpose" value="${esc(c.purpose||'')}" placeholder="A short reason for this business expense"></label><label class="field full attachment-box">Bill / invoice — required<input name="receiptFile" aria-label="Bill attachment" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"><small>PDF, JPG, PNG or WebP · max 10 MB · stored in this browser for the demo.</small>${c.receiptKey?`<small>Existing proof: ${esc(c.receipt)}</small>`:''}<span><input type="checkbox" name="sample" aria-label="Use a fictional demo bill"> Generate a clearly labelled fictional bill for this demo</span></label><details class="full"><summary>Optional reference and prior approval</summary><div class="formgrid" style="margin-top:12px"><label class="field">Invoice reference<input name="invoice" value="${esc(c.invoice||'')}" placeholder="Optional if present on the bill"></label><label class="field">Prior approval reference<input name="prior" value="${esc(c.prior||'')}" placeholder="If your policy requires it"></label><label class="field">Paid using<select name="paidBy">${['Personal','Company'].map(v=>`<option ${v===(c.paidBy||'Personal')?'selected':''}>${v}</option>`).join('')}</select></label></div></details><div class="notice full" id="estimate"></div></div><div class="formactions"><button type="button" onclick="closeModal()">Cancel</button><button type="button" onclick="submitForm(true,'${c.id||''}')">Save draft</button><button class="primary" type="submit">Submit for review →</button></div></form>`);categoryFields(c);$('#claimForm').onsubmit=e=>{e.preventDefault();submitForm(false,c.id)};preview();}
function inputField(label,name,type,value,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value||'')}" ${extra}></label>`;}
function categoryFields(initial){const f=$('#claimForm'),v=initial&&typeof initial==='object'?initial:Object.fromEntries(new FormData(f)),def=s.categoryDefs[f.category.value];let html='';switch(def.kind){case 'subscription':html=inputField('Plan','plan','text',v.plan,'required placeholder="e.g. Plus / Pro / Business"')+`<label class="field">Billing cycle<select name="cycle"><option ${v.cycle!=='Annual'?'selected':''}>Monthly</option><option ${v.cycle==='Annual'?'selected':''}>Annual</option></select></label>`;break;case 'travel':html=inputField('Destination / route','destination','text',v.destination,'required');break;case 'purchase':html=inputField('Item purchased','item','text',v.item,'required')+inputField('Quantity','quantity','number',v.quantity||1,'required min="1" step="1"');break;case 'training':html=inputField('Course / training name','course','text',v.course,'required');break;}$('#categoryFields').innerHTML=html?`<p class="sub">${esc(def.note)}</p><div class="formgrid">${html}</div>`:'';$('#categoryFields').hidden=!html;}
function preview(){const f=$('#claimForm'),cur=f.currency.value,amount=+f.amount.value;$('#estimate').innerHTML=`<strong>${cad(amount*s.rates[cur])} estimated</strong> · 1 ${cur} = ${s.rates[cur]} CAD<br>${esc(s.source)}<br><strong>Approval:</strong> HR / Super Admin review<br>Personal work purchases only. Company-paid purchases are not reimbursable.`;}
async function submitForm(draft,id){const f=$('#claimForm'),button=f.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;try{const editingActor=actor(),editingRole=role(),fd=new FormData(f),c=Object.fromEntries(fd);c.amount=+c.amount;c.mealDates=[c.date];c.period=c.date.slice(0,7);delete c.receiptFile;delete c.sample;const old=id?s.claims.find(x=>x.id===id):null;if(old&&(!['Draft','Needs Information','Submitted','Awaiting HR','Approved'].includes(old.status)||!admin()&&old.employee!==person()))throw Error('This claim cannot be edited.');const oldSnapshot=JSON.stringify(old);const file=f.receiptFile.files[0]||(f.sample.checked?await ExpenseReceipts.sample(c):null);if(file)Object.assign(c,await ExpenseReceipts.put(file));else if(old?.receiptKey)Object.assign(c,{receipt:old.receipt,receiptKey:old.receiptKey,receiptHash:old.receiptHash,receiptType:old.receiptType,receiptSize:old.receiptSize});if(!draft&&!c.receiptKey)throw Error('A bill or invoice attachment is required.');const current=id?s.claims.find(x=>x.id===id):null;if(id&&(!current||!['Draft','Needs Information','Submitted','Awaiting HR','Approved'].includes(current.status)||!admin()&&current.employee!==person()))throw Error('This claim changed during upload. Reopen it before editing.');if(current&&current.employeeId!==old.employeeId)throw Error('Claim ownership changed during upload. Reopen it.');if(actor()!==editingActor||role()!==editingRole)throw Error('Your preview account changed during upload. Reopen the form.');if(current&&JSON.stringify(current)!==oldSnapshot)throw Error('This claim was updated during upload. Reopen it before saving.');if(current){c.employeeId=current.employeeId;c.employee=current.employee;}const before=structuredClone(s);if(id)s.claims=s.claims.filter(x=>x.id!==id);try{if(draft){c.id=id||'EXP-'+crypto.randomUUID().slice(0,8);c.status='Draft';c.stage='Draft';s.claims.push(c);E.log(s,person(),'Saved draft '+c.id);}else E.submit(s,{...c,id});}catch(e){s=before;throw e;}save();closeModal();toast(draft?'Draft saved.':'Submitted to HR / Super Admin for validation.');}catch(e){toast(e.message);}finally{button.disabled=false;}}
async function previewReceipt(id){try{const c=s.claims.find(x=>x.id===id);if(!c||!E.canRead(c,role(),actor()))throw Error('Receipt access denied.');const r=await ExpenseReceipts.get(c.receiptKey);if(!r)throw Error('Attachment is missing in this browser. Ask the claimant to reattach the bill.');const url=URL.createObjectURL(r.blob);modal(`<h2>Bill / invoice proof</h2><p class="sub">${esc(r.name)} · ${c.receiptKey.startsWith('builtin:')?'Fictional seeded evidence':'Browser-stored attachment'}</p>${r.type==='application/pdf'?`<iframe title="Invoice PDF preview" class="proof-preview" src="${url}"></iframe>`:`<img class="proof-image" src="${url}" alt="Uploaded expense proof">`}<a href="${url}" download="${esc(r.name)}">Download attachment</a>`);$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}catch(e){toast(e.message);}}
function detail(id){const c=s.claims.find(x=>x.id===id);if(!c||!E.canRead(c,role(),actor()))return;const canReview=E.canReview(c,role(),actor());modal(`<h2>${esc(c.vendor)}</h2><div class="flex">${pill(c.status)}<span class="sub">${esc(c.id)}</span></div><div class="detail">${[['Employee',c.employee],['Employee ID',c.employeeId||'Ownership verification required'],['Category',c.category],['Original amount',orig(c)],['CAD '+(c.lockedCAD!=null?'locked':'estimate'),cad(value(c))],['Rate / CAD per unit',c.lockedRate??s.rates[c.currency]],['Rate source / as of',c.batch?((s.batches.find(b=>b.id===c.batch)?.source||'')+' · '+(s.batches.find(b=>b.id===c.batch)?.rateTime||'')):s.source+' · '+s.rateTime],['Plan',c.plan||'—'],['Prior approval',c.prior||'—'],['Expense date',c.date],['Reviewer',c.reviewer],['Invoice',c.invoice],['Billing period',c.period||'—'],['Category details',ExpenseCategories.summary(c)],['HR final approval',c.approvals?.hr?.status||'Pending'],['Receipt',c.receipt||'Not attached'],['Purpose',c.purpose],['Batch',c.batch||'Not assigned'],['Decision',c.reason||'Not reviewed']].map(([k,v])=>`<div><small>${esc(k)}</small>${esc(v)}</div>`).join('')}</div><button onclick="previewReceipt('${id}')">View bill / invoice</button><div class="approval-track"><span>HR / Super Admin validation · ${esc(c.approvals?.hr?.status||'Pending')}</span></div>${c.flag?`<div class="notice amber">${esc(c.flag)} Resolve this in the decision reason before approval.</div>`:''}${admin()&&!c.employeeId&&!c.batch?`<div class="notice amber">Legacy claim: verify the original employee ID against the bill before approval.<button onclick="verifyOwner('${id}')">Verify original owner</button></div>`:''}${canReview?`<form id="reviewForm"><div class="formgrid"><label class="field">Decision<select name="status"><option>Approved</option><option>Needs Information</option><option>Rejected</option></select></label><label class="field">Approved amount (${c.currency})<input name="amount" type="number" step=".01" max="${c.amount}" value="${c.amount}"></label><label class="field full">Decision / flag resolution reason<textarea name="reason" required placeholder="Explain the decision or request missing details"></textarea></label></div><div class="formactions"><button class="primary">Save decision</button></div></form>`:''}${(admin()||c.employee===person())&&['Draft','Needs Information','Approved','Submitted','Awaiting HR'].includes(c.status)?`<div class="formactions"><button onclick="newClaim(s.claims.find(x=>x.id==='${id}'))">Edit / respond${c.status==='Approved'?' · sends back to review':''}</button></div>`:'<p class="sub">Only the claimant or HR can edit unreleased claim details. Assigned reviewers record a decision above; released claims remain locked.</p>'}`);if(canReview)$('#reviewForm').onsubmit=e=>{e.preventDefault();act(()=>{const f=e.target;E.review(s,id,role(),actor(),f.status.value,f.reason.value,+f.amount.value);closeModal();toast('Decision saved.')})}}
function payouts(){if(!admin())return head('Payouts','Reimbursements stay separate from salaries.')+'<div class="notice">Only HR or Super Admin can reserve, release, sync or confirm a payout.</div>';return head('Prepare once. Pay once.','Use an actual cutoff, not a calendar-month reset.','<button class="primary" onclick="newBatch()">＋ Prepare payout</button>')+'<div class="notice">Approved & unpaid → reserve exact claims and lock FX → sync expense sheet → confirm actual payment. Changing the scheduled date never adds the claims twice.</div>'+`<div class="card"><div class="cardhead"><h2>Payout batches</h2><span class="sub">${s.batches.length} batches</span></div>${s.batches.map(b=>`<div class="batch"><div class="flex" style="justify-content:space-between"><div><h3>${esc(b.employee)} <span class="sub">/ ${esc(b.id)}</span></h3><p class="sub">Scheduled ${esc(b.date)} · ${b.ids.length} claim(s) · Cutoff ${esc(b.cutoff||'2026-11-04')}</p></div><div><strong>${cad(b.total)}</strong> ${pill(b.status)}</div></div><p class="sub">${esc(b.ids.join(' · '))}<br>FX locked: ${esc(b.source)} · ${esc(b.rateTime)}${b.reference?'<br>Payment reference: '+esc(b.reference)+' · '+esc(b.paidDate||b.date):''}</p><div class="flex">${['Reserved','Synced','Failed'].includes(b.status)?`<button onclick="syncBatch('${b.id}')">${b.status==='Synced'?'Retry sync (safe)':'Sync to demo sheet'}</button><button onclick="syncBatch('${b.id}',true)">Test sync failure</button><button onclick="reschedule('${b.id}')">Change pay date</button><button onclick="cancelBatch('${b.id}')">Cancel batch</button>`:''}${b.status==='Synced'?`<button class="primary" onclick="payment('${b.id}')">Confirm payment</button><button onclick="failed('${b.id}')">Payment failed</button><button onclick="uncertain('${b.id}')">Payment uncertain</button>`:''}${b.status==='Uncertain'?`<button onclick="reconcile('${b.id}')">Reconcile transfer</button>`:''}</div></div>`).join('')}</div>`}
function newBatch(){modal(`<h2>Prepare an expense payout</h2><p class="sub">Only approved, unpaid claims before the cutoff are included. FX and claim amounts lock together.</p><form id="batchForm"><div class="formgrid"><label class="field">Employee<select name="employee">${s.employees.map(e=>`<option>${esc(e.name)}</option>`).join('')}</select></label><label class="field">Scheduled pay date<input required type="date" name="date" value="2026-12-08"></label><label class="field full">Expense cutoff<input required type="datetime-local" name="cutoff" value="2026-11-11T23:59"></label></div><div class="notice" style="margin-top:20px">No salary amount is needed. Late older claims remain eligible until reimbursed.</div><div class="formactions"><button class="primary">Reserve claims & lock CAD</button></div></form>`);$('#batchForm').onsubmit=e=>{e.preventDefault();act(()=>{const f=e.target,b=E.batch(s,f.employee.value,f.cutoff.value,f.date.value);closeModal();toast(b.ids.length+' claims reserved. '+cad(b.total)+' locked.')})}}
function syncBatch(id,fail){act(()=>{if(!admin())throw Error('HR access required.');try{E.sync(s,id,fail)}catch(e){save();throw e}toast('Synced and reconciled. '+s.ledger.filter(x=>x.batch===id).length+' unique rows.');})}function cancelBatch(id){act(()=>{if(!admin())throw Error('HR access required.');E.cancel(s,id);toast('Batch cancelled. Claims returned to Approved & Unpaid.')})}function reschedule(id){const b=s.batches.find(x=>x.id===id);modal(`<h2>Change scheduled date</h2><form id="scheduleForm"><label class="field">New date<input required type="date" name="date" value="${b.date}"></label><div class="formactions"><button class="primary">Save date</button></div></form>`);$('#scheduleForm').onsubmit=e=>{e.preventDefault();act(()=>{b.date=e.target.date.value;E.log(s,'HR','Rescheduled '+id+'; claim IDs unchanged');closeModal()})}}
function payment(id){modal(`<h2>Confirm reimbursement payment</h2><p class="sub">Confirm only after the transfer succeeds. Salary payment alone is not enough.</p><form id="payForm"><div class="formgrid"><label class="field">Actual payment date<input required type="date" name="date" value="2026-12-08"></label><label class="field">Transfer reference<input required name="reference" placeholder="e.g. DEMO-DEC-008"></label></div><div class="formactions"><button class="primary">Confirm paid</button></div></form>`);$('#payForm').onsubmit=e=>{e.preventDefault();act(()=>{E.pay(s,id,e.target.date.value,e.target.reference.value);closeModal();toast('Payment confirmed. These claims cannot enter another payout.')})}}function failed(id){act(()=>{const b=s.batches.find(x=>x.id===id);b.status='Failed';E.log(s,'HR','Payment failed '+id+'; claims remain reserved, not paid');toast('Not paid. Retry this batch safely or cancel to release claims.')})}function uncertain(id){act(()=>{s.batches.find(x=>x.id===id).status='Uncertain';E.log(s,'HR','Transfer uncertain '+id+'; retry blocked until reconciled');toast('Batch held. Reconcile the transfer before any retry.')})}function reconcile(id){modal(`<h2>Reconcile uncertain transfer</h2><p class="sub">Check the payment provider before selecting an outcome.</p><div class="flex"><button onclick="act(()=>{s.batches.find(x=>x.id==='${id}').status='Synced';E.log(s,'HR','Uncertain transfer reconciled ${id}');closeModal();payment('${id}')})">Succeeded · add reference</button><button onclick="act(()=>{s.batches.find(x=>x.id==='${id}').status='Failed';E.log(s,'HR','Confirmed not sent ${id}');closeModal()})">Confirmed not sent</button></div>`)}
function legacyLedger(){if(!admin())return head('Payroll sync','HR and Super Admin only.')+'<div class="notice">Employees can see their own claims only.</div>';const book=E.reimbursementSummary(s),batches=s.batches.filter(b=>['Reserved','Synced','Failed'].includes(b.status)||b.status==='Paid'&&s.ledger.some(r=>r.batch===b.id));if(!window.selectedPayroll||!batches.some(b=>b.id===window.selectedPayroll))window.selectedPayroll=batches[0]?.id||'';const id=window.selectedPayroll,b=s.batches.find(b=>b.id===id);let rec;try{rec=id?E.reconcile(s,id):null;}catch{}return head('Reimbursements, clearly accounted for.','See approved, paid and outstanding reimbursements in one place.')+`<div class="stats"><div class="stat"><small>HR APPROVED CAD</small><strong>${cad(book.approvedCAD)}</strong><em>Snapshot at HR approval</em></div><div class="stat"><small>FX ADJUSTMENT CAD</small><strong>${cad(book.fxAdjustmentCAD)}</strong><em>Difference locked at payout release</em></div><div class="stat"><small>PAID CAD</small><strong>${cad(book.paidCAD)}</strong><em>Confirmed reimbursements only</em></div><div class="stat featured"><small>OUTSTANDING CAD</small><strong>${cad(book.outstandingCAD)}</strong><em>${book.balanced?'✓ Reconciles':'⚠ Review required'}</em></div></div><div class="notice"><strong>Approved + locked FX adjustment = Paid + Outstanding.</strong><br>This is a reimbursement subledger, not a full company accounting system. Original currencies remain separate; CAD combines approved snapshots and locked payout values. Salary data stays outside this portal.</div><section class="card"><div class="cardbody"><h2>Original-currency balances</h2>${Object.entries(book.original).map(([cur,t])=>`<div class="metricline"><strong>${esc(cur)}</strong><span>Approved ${t.approved.toFixed(2)} · Paid ${t.paid.toFixed(2)} · Outstanding ${t.outstanding.toFixed(2)}</span></div>`).join('')||'<p class="sub">No HR-approved claims yet.</p>'}</div></section><div class="grid"><section class="card"><div class="cardbody"><h2>Payroll sync · HR quick guide</h2><ol class="payroll-steps"><li><strong>Review bills.</strong> Open Approval inbox; approve the eligible original amount or request information.</li><li><strong>Prepare payout.</strong> Choose employee, expense cutoff and scheduled pay date. Only approved, unpaid claims are reserved; each gets a locked CAD value.</li><li><strong>Check the batch.</strong> Choose it below, preview exact rows and confirm Claim IDs, Employee ID, currencies and CAD total.</li><li><strong>Sync or export.</strong> Run demo sync, then require “Rows and totals match”. CSV works now; automatic Google writes need the production connector.</li><li><strong>Add to payroll once.</strong> In the separate salary workbook, select this Batch ID and Employee ID. Import only its reimbursement total, never all historical expenses.</li><li><strong>Confirm the transfer.</strong> After actual reimbursement succeeds, open Payouts → Confirm payment and enter its date/reference. If unsure, use Payment uncertain and reconcile before retrying.</li></ol><p class="sub">Early or late salary dates do not reset expenses. Paid claims stay in history; unpaid and late older claims stay eligible for a later batch.</p><div class="notice amber"><strong>Demo mode — no real Google Sheet writes.</strong><br>Preview the exact expense-only data, test sync/retry and download CSV. Production needs a server connector and access to an expense-only spreadsheet.</div><label class="field">Payout batch<select onchange="window.selectedPayroll=this.value;render()">${batches.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.employee)} · ${esc(x.id)} · ${cad(x.total)}</option>`).join('')||'<option>No released payout batch</option>'}</select></label>${b?`<div class="ratebox"><strong>${esc(b.employee)} · ${esc(b.id)}</strong><br>${b.ids.length} claims · ${cad(b.total)} locked CAD · ${pill(b.status)}<br>Reconciliation: ${rec?.ok?'✓ Rows and totals match':'Not synced or needs repair'}<br>Expected ${rec?.expectedCount??b.ids.length} rows / ${cad(rec?.expectedCAD??b.total)} · Sheet ${rec?.actualCount??0} rows / ${cad(rec?.actualCAD??0)}</div><div class="flex" style="margin-top:16px"><button onclick="previewPayroll()">Preview data</button>${b.status!=='Paid'?`<button class="primary" onclick="syncBatch('${b.id}')">${b.status==='Synced'?'Retry demo sync safely':'Run demo sync'}</button><button onclick="syncBatch('${b.id}',true)">Test sync failure</button>`:''}<button onclick="downloadCSV()">Download ledger CSV</button><button onclick="downloadSummary()">Download payroll total CSV</button></div>`:'<p class="sub">Prepare an HR-approved payout batch first.</p>'}<p class="sub" style="margin-top:16px">Last demo attempt: ${esc(s.syncSettings.lastAttempt||'None')}<br>Last demo success: ${esc(s.syncSettings.lastSuccess||'None')}<br>${esc(s.syncSettings.lastError||'No sync errors recorded')}</p></div></section><section class="card"><div class="cardbody"><h2>Connection mapping</h2><p class="sub">These are planning settings, not a connected payroll account. Never upload credentials or base salaries here.</p><form id="syncMapping" onsubmit="saveSyncMapping(event)"><label class="field">Expense-only Google Sheet ID / URL<input name="spreadsheet" value="${esc(s.syncSettings.spreadsheetId||'')}" placeholder="Paste the separate expense export sheet URL"></label><label class="field">Ledger tab<input name="ledger" value="${esc(s.syncSettings.ledgerTab||'Expense_Ledger')}" required></label><label class="field">Summary tab<input name="summary" value="${esc(s.syncSettings.summaryTab||'Payout_Summary')}" required></label><button style="margin-top:12px">Save demo mapping</button></form><ol class="sub"><li>Portal server writes frozen batch rows to the expense-only sheet.</li><li>Upsert by Batch ID + Claim ID; verify unique rows and CAD total.</li><li>The existing salary workbook imports the selected batch total by Employee ID.</li><li>HR confirms the actual payment separately. Sheet sync never means Paid.</li></ol><button onclick="sheetGuide()">View column mapping & import formula</button></div></section></div><section class="card"><div class="cardhead"><h2>Expense export ledger</h2><span class="sub">${s.ledger.length} unique rows</span></div><div class="scroll"><table><thead><tr><th>CLAIM / BATCH</th><th>EMPLOYEE</th><th>ORIGINAL</th><th>LOCKED RATE</th><th>PAYABLE CAD</th><th>PAYMENT</th></tr></thead><tbody>${s.ledger.map(r=>`<tr><td>${esc(r.claim)}<small>${esc(r.batch)}</small></td><td>${esc(r.employee)}<small>${esc(r.employeeId)}</small></td><td>${esc(r.currency)} ${r.original.toFixed(2)}<small>Approved ${r.approved.toFixed(2)}</small></td><td>${r.rate}</td><td>${cad(r.cad)}</td><td>${pill(r.paymentStatus||'Unpaid')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Sync a released batch to populate the expense ledger.</td></tr>'}</tbody></table></div></section>`;}
function saveSyncMapping(e){e.preventDefault();if(!admin())return;act(()=>{const f=e.target,raw=f.spreadsheet.value.trim(),id=raw.match(/\/spreadsheets\/d\/([A-Za-z0-9_-]+)/)?.[1]||raw;if(id&&!/^[A-Za-z0-9_-]{20,}$/.test(id))throw Error('Use a valid spreadsheet ID or Google Sheets URL.');const ledger=f.ledger.value.trim(),summary=f.summary.value.trim();if(!ledger||!summary||ledger===summary||/[\[\]*?:/\\]/.test(ledger+summary))throw Error('Choose two valid, different tab names.');Object.assign(s.syncSettings,{spreadsheetId:id,ledgerTab:ledger,summaryTab:summary});E.log(s,actor(),'Saved expense-only sheet mapping (demo; no connection granted)');toast('Mapping saved for demonstration. Google Sheets is not connected.');});}
function previewPayroll(){try{const rows=E.exportRows(s,window.selectedPayroll);modal(`<h2>Exact payout data</h2><p class="sub">Frozen values only. No salary fields or fresh-rate recalculation.</p><pre class="payload">${esc(JSON.stringify(rows,null,2))}</pre>`);}catch(e){toast(e.message);}}
function csvDownload(name,headers,rows){const safe=v=>'"'+(/^[=+@\-]/.test(String(v??''))?"'":'')+String(v??'').replace(/"/g,'""')+'"';const text=[headers.map(safe).join(','),...rows.map(r=>r.map(safe).join(','))].join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
function downloadCSV(){if(!admin())return;try{const rows=E.exportRows(s,window.selectedPayroll);csvDownload('expense-ledger-'+window.selectedPayroll+'.csv',['Batch ID','Claim ID','Employee ID','Original Amount','Currency','Approved Original','Locked CAD Rate','Payable CAD','Sync Status','Payment Status','Payment Reference','Paid Date'],rows.map(r=>[r.batch,r.claim,r.employeeId,r.original,r.currency,r.approved,r.rate,r.cad,s.batches.find(b=>b.id===r.batch)?.status==='Reserved'?'Not synced':r.syncStatus,r.paymentStatus,r.paymentReference,r.paidDate]));}catch(e){toast(e.message);}}
function downloadSummary(){if(!admin())return;try{const rows=E.exportRows(s,window.selectedPayroll);csvDownload('payroll-expense-total-'+window.selectedPayroll+'.csv',['Batch ID','Employee ID','Reimbursement CAD','Claim Count'],[[window.selectedPayroll,rows[0]?.employeeId,E.round(rows.reduce((a,r)=>a+r.cad,0)),rows.length]]);}catch(e){toast(e.message);}}
function sheetGuide(){modal(`<h2>Payroll sheet mapping</h2><p class="sub">Use a separate expense-only file. The portal connector must have no access to the salary workbook.</p><p>A Batch ID · B Claim ID · C Employee ID · D Original Amount · E Currency · F Approved Original · G Locked CAD Rate · H Payable CAD · I Sync Status · J Payment Status · K Payment Reference · L Paid Date</p><p class="sub">After the salary workbook owner imports the selected expense export into an Expense_Ledger tab, A2 is the chosen Batch ID and B2 is the employee’s ID:</p><pre class="payload">=SUMIFS(Expense_Ledger!H:H,Expense_Ledger!A:A,A2,Expense_Ledger!C:C,B2,Expense_Ledger!I:I,"Synced")</pre><p class="sub"><strong>Setup:</strong> Create a separate expense-only Google spreadsheet with Expense_Ledger and Payout_Summary tabs. Save its URL in Connection mapping. Production: an authorized server service writes only this expense file; the salary workbook owner uses IMPORTRANGE or the CSV to bring the reimbursement data into payroll. Never share the salary workbook with the portal connector.</p><p class="sub"><strong>Monthly operation:</strong> Choose the intended Batch ID in payroll, match immutable Employee IDs, verify the imported total against the portal and record the batch as processed. Keep that batch selection in payroll history. Changing months must use a new batch; do not reuse a prior paid batch.</p><p class="sub"><strong>Failure handling:</strong> Failed sync → retry the same batch. Mismatched rows/totals → repair/resync before payment. Transfer uncertain → check the provider before retry. Cancel only after confirming no money was sent; synced export rows must be voided or removed before payroll uses them.</p><p class="sub">Import only the intended batch once. Paid history stays visible but is never automatically summed into a new payroll. Retries update the same IDs. A production worker must reconcile counts/totals and retain void/revision history.</p>`);}
function controls(){if(!admin())return head('Employee workspace','Use My expenses to track your reimbursements.');return head('Confidence, built into the flow.','Explore the rules, test edge cases and see the audit trail.')+`<div class="grid"><div><section class="card"><div class="cardhead"><h2>Proof lab</h2><button class="primary" onclick="runProof()">Run safeguard tests</button></div><div class="cardbody"><p class="sub">Tests use an isolated copy of the demo data. Your workspace is unchanged.</p><div id="proof">Duplicate invoices · self-approval · locked FX · late claims · retry safety · failed sync · salary separation</div></div></section><section class="card"><div class="cardbody"><h2>Category forms & routing</h2><button onclick="addCategory()">＋ Add expense category</button><p class="sub">All categories use one validation step: HR or Super Admin. Employees submit and track their own expenses.</p>${Object.entries(s.rules).map(([cat,r])=>`<div class="metricline"><span>${esc(cat)}<br><small class="muted">Demo policy, CAD limit / prior approval</small></span><div class="flex"><label><input type="checkbox" aria-label="Covered ${esc(cat)}" ${s.policies[cat].covered?'checked':''} ${!admin()?'disabled':''} onchange="s.policies['${cat}'].covered=this.checked;E.log(s,'HR','Coverage changed: ${cat}');save()"> Covered</label><input type="number" aria-label="CAD limit ${esc(cat)}" style="width:75px" min="1" value="${s.policies[cat].limit}" ${!admin()?'disabled':''} onchange="if(+this.value>0){s.policies['${cat}'].limit=+this.value;E.log(s,'HR','Policy limit changed: ${cat}');save()}"><label><input type="checkbox" aria-label="Prior approval ${esc(cat)}" ${s.policies[cat].prior?'checked':''} ${!admin()?'disabled':''} onchange="s.policies['${cat}'].prior=this.checked;E.log(s,'HR','Prior approval rule changed: ${cat}');save()"> Prior approval</label></div></div>`).join('')}</div></section><section class="card"><div class="cardhead"><h2>Activity trail</h2><span class="sub">${s.audit.length} events</span></div><div class="cardbody">${s.audit.slice(0,30).map(a=>`<div class="step"><span class="num">↗</span><div><strong>${esc(a.action)}</strong><p>${esc(a.actor)} · ${esc(new Date(a.time).toLocaleString())}</p></div></div>`).join('')||'<p class="sub">Your actions will appear here.</p>'}</div></section></div><div><section class="card"><div class="cardbody"><h2>Exchange rates</h2><div class="ratebox">${esc(s.source)}<br>${esc(s.rateTime)}<br>${s.stale?'⚠ Stale: payout release blocked':'✓ Snapshot available'}</div><p class="sub">Fixture rates are for demonstration, not financial use. Fetch latest attempts a public daily quote; it is labelled with its actual rate date.</p><div class="flex"><button onclick="fetchRates()">Fetch latest quote</button>${admin()?'<button onclick="manualRates()">Confirm rates manually</button><button onclick="shiftRates()">Simulate FX change</button><button onclick="act(()=>{s.stale=!s.stale;E.log(s,\'HR\',\'Toggled stale rate test\')})">Toggle stale rate</button>':''}</div></div></section><section class="card"><div class="cardbody"><h3>Demo boundaries</h3><p class="sub">Role switching is for presentation, not authentication. Records stay in this browser. Production needs server permissions, database transactions, private receipt storage, receipt hashing, policy configuration and Google Sheets credentials.</p><button onclick="resetDemo()">Load 28 fictional scenarios</button><button onclick="resetDemo(true)">Start with zero expenses</button></div></section></div></div>`}
async function fetchRates(){toast('Fetching latest provider quote…');try{const r=await fetch('https://open.er-api.com/v6/latest/CAD');if(!r.ok)throw Error();const j=await r.json();if(j.result!=='success')throw Error();const nextRates={};for(const k of Object.keys(s.rates)){const rate=j.rates?.[k];if(!Number.isFinite(rate)||rate<=0)throw Error('Currency missing');nextRates[k]=1/rate;if(!Number.isFinite(nextRates[k])||nextRates[k]<=0)throw Error('Invalid currency rate');}const nextTime=new Date(j.time_last_update_unix*1000).toISOString();if(Date.parse(nextTime)>Date.now()+300000)throw Error('Quote is in the future');Object.assign(s,{rates:nextRates,rateTime:nextTime,source:'ExchangeRate-API · daily quote',stale:Date.now()-Date.parse(nextTime)>48*3600000});E.log(s,'System','Updated provider quote');save();toast('Quote updated. Paid and reserved CAD amounts are unchanged.')}catch{toast('Provider unavailable. Existing rates retained and labelled.');}}
function manualRates(){if(!admin())return;modal(`<h2>Confirm an FX snapshot</h2><p class="sub">HR confirms every listed rate as CAD per 1 currency unit. This is a manual rate, not a provider live quote.</p><form id="manualFX"><div class="formgrid">${Object.keys(s.rates).map(k=>`<label class="field">${k} → CAD<input required type="number" step="any" min="0.00000001" name="${k}" value="${s.rates[k]}" ${k==='CAD'?'readonly':''}></label>`).join('')}<label class="field full">Source / reason<textarea required name="reason" placeholder="Source checked and reason for manual confirmation"></textarea></label></div><div class="formactions"><button class="primary">Confirm snapshot</button></div></form>`);$('#manualFX').onsubmit=e=>{e.preventDefault();act(()=>{const f=e.target;for(const k of Object.keys(s.rates)){const n=+f.elements[k].value;if(!Number.isFinite(n)||n<=0)throw Error('Every rate must be positive.')}for(const k of Object.keys(s.rates))s.rates[k]=+f.elements[k].value;s.rates.CAD=1;s.rateTime=new Date().toISOString();s.source='HR-confirmed · '+f.reason.value;s.stale=false;E.log(s,'HR','Confirmed manual FX snapshot: '+f.reason.value);closeModal();toast('Manual snapshot recorded. Locked payments are unchanged.');})};}function shiftRates(){act(()=>{for(const k of Object.keys(s.rates))if(k!=='CAD')s.rates[k]*=1.1;s.rateTime=new Date().toISOString();s.source='Simulated +10% fixture · not live';s.stale=false;E.log(s,'HR','Simulated FX change; locked amounts unchanged');toast('Unpaid estimates changed. Released and paid amounts remain locked.')})}function resetDemo(empty=false){if(!admin())return;modal(`<h2>${empty?'Start a clean test?':'Load expanded demo data?'}</h2><p class="sub">Replaces browser-local expense records only. ${empty?'Zero claims, zero batches, zero totals.':'28 fictional claims across currencies and review states.'} Portal employees and permissions are retained. No real data or payments.</p><div class="formactions"><button onclick="closeModal()">Keep changes</button><button class="primary" onclick="applyDataset(${empty})">${empty?'Start empty':'Load scenarios'}</button></div>`);}
function applyDataset(empty){if(!admin())return;const directory=s.employees,link=s.payrollLink,settings=s.syncSettings;s=E.demoSeed(empty);s.employees=directory;if(link)s.payrollLink=link;s.syncSettings=settings;if(hostContext){s.employees=directory;mapHostSeed();}window.selectedPayroll='';window.selectedRun='';payrollPreview=null;save();closeModal();toast(empty?'Clean test workspace ready.':'Expanded fictional scenarios ready.');}
function mapHostSeed(){if(!hostContext)return;const names=['Nadia Rahman','Arif Ahmed','Maya Hasan'],people=hostContext.employees.filter(e=>e.role==='Employee');const mapping=Object.fromEntries(names.map((n,i)=>[n,people[i%Math.max(people.length,1)]?.name||hostContext.employee]));for(const c of s.claims)if(mapping[c.employee]&&String(c.employeeId||'').startsWith('DEMO-')){c.employee=mapping[c.employee];c.employeeId=hostContext.employees.find(e=>e.name===c.employee)?.id;}for(const b of s.batches)if(mapping[b.employee]&&String(b.employeeId||'').startsWith('DEMO-')){b.employee=mapping[b.employee];b.employeeId=hostContext.employees.find(e=>e.name===b.employee)?.id;}s.employees=hostContext.employees;s.hostInitialized=true;}
function runProof(){const tests=[],ok=v=>{if(!v)throw Error('Assertion failed')},blocked=fn=>{let b=false;try{fn()}catch{b=true}ok(b)},test=(name,fn)=>{try{fn();tests.push({name,pass:true})}catch(e){tests.push({name,pass:false,error:e.message})}};
test('Employee / manager cannot approve',()=>blocked(()=>E.review(E.seed(),'EXP-1001','Employee','Arif Ahmed','Approved','Checked',20)));
test('HR approves directly',()=>{const t=E.seed();E.review(t,'EXP-1001','HR','Demo HR','Approved','Checked',20);ok(t.claims[0].status==='Approved')});
test('Super Admin validates directly',()=>{const t=E.seed();E.review(t,'EXP-1001','Super Admin','Demo Admin','Approved','Checked',20);ok(t.claims[0].status==='Approved')});
test('Self approval blocked',()=>blocked(()=>E.review(E.seed(),'EXP-1001','HR','Nadia Rahman','Approved','Checked',20)));
test('Duplicate bill blocked',()=>{const t=E.seed();blocked(()=>E.submit(t,{...t.claims[0],id:''}))});
test('Sync retry preserves unique rows',()=>{const t=E.seed(),b=E.batch(t,'Arif Ahmed','2026-11-11','2026-12-08');E.sync(t,b.id);E.sync(t,b.id);ok(E.reconcile(t,b.id).ok&&t.ledger.length===1)});
test('Corrupted sheet blocks payment',()=>{const t=E.seed(),b=E.batch(t,'Arif Ahmed','2026-11-11','2026-12-08');E.sync(t,b.id);t.ledger[0].cad++;blocked(()=>E.pay(t,b.id,'2026-12-08','DEMO'))});
test('Empty workspace has zero totals',()=>{const t=E.demoSeed(true);ok(t.claims.length===0&&E.reimbursementSummary(t).totalCAD===0)});
$('#proof').innerHTML=`<h3>${tests.filter(x=>x.pass).length}/${tests.length} safeguards passed</h3>`+tests.map(t=>`<div class="result ${t.pass?'pass':'fail'}">${t.pass?'✓':'✕'} ${esc(t.name)} ${esc(t.error||'')}</div>`).join('');}
const P=ExpensePayroll;let payrollDraft=null,payrollPreview=null;
function payrollDefaults(){const now=E.businessDate(),c=P.cycle(now,10);return {month:now.slice(0,7),payDay:10,...c,paymentDate:now>c.scheduled?now:c.scheduled,employee:'',includeLate:true};}
function ledger(){if(!admin())return head('Payroll sync','HR / Super Admin only.');const d=payrollDraft||payrollDefaults(),runs=s.payrollRuns||[];if(!window.selectedRun||!runs.some(r=>r.id===window.selectedRun))window.selectedRun=runs[0]?.id||'';const selected=runs.find(r=>r.id===window.selectedRun);let totals=[],problem='';if(selected)try{totals=P.summary(s,selected.id)}catch(e){problem=e.message;}return head('Payroll, without the copying.','Connect emails once. Choose a period. Sync eligible expenses with one click.')+emailSetupCard()+`<div class="notice"><strong>Recommended: a fixed monthly cycle + unpaid claim tracking.</strong><br>Pay day 10 → previous month’s 10th through this month’s 9th. The actual transfer may be early or late; it never resets the cycle or repeats paid claims. Expense forms still use one specific date.</div><div class="sync-flow"><span>1 · Choose period</span><span>2 · Review & freeze</span><span>3 · Export / link</span><span>4 · Confirm actual payment</span></div><section class="card"><div class="cardbody"><h2>1. Choose your payroll period</h2><form id="payrollPeriod" onsubmit="previewPeriod(event)"><div class="formgrid"><label class="field">Cycle month<input type="month" name="month" value="${esc(d.month)}" required></label><label class="field">Usual pay day<input type="number" min="1" max="31" name="payDay" value="${d.payDay}" required></label><div class="full flex"><button type="button" onclick="applyPayCycle()">Use monthly cycle</button><button type="button" onclick="applyRolling()">Use 30 days ending on payment date</button><small class="muted">Monthly cycle is recommended. Use separate runs for employees with different pay cycles. Custom dates are also supported.</small></div><label class="field">Expense period from<input type="date" name="from" value="${d.from}" required></label><label class="field">Expense period to<input type="date" name="to" value="${d.to}" required></label><label class="field">Planned actual payment date<input type="date" name="paymentDate" value="${d.paymentDate}" required></label><label class="field">Employees<select name="employee"><option value="">All employees</option>${s.employees.map(e=>`<option ${d.employee===e.name?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><label class="full"><input name="includeLate" type="checkbox" ${d.includeLate?'checked':''}> Include older approved, unpaid claims as a separate “Late unpaid” total</label></div><div class="formactions"><button type="button" class="primary" onclick="quickSyncPeriod()">Sync expenses for this period</button><button>Preview details first</button></div></form><p class="sub">Dates use Asia/Dhaka. Both dates are inclusive. Before this period = late unpaid. After period / planned transfer / today = excluded. Draft, rejected, unapproved, paid, reserved, company-paid and uncovered claims stay out.</p></div></section>${payrollPreview?periodPreviewHTML(payrollPreview):''}<section class="card"><div class="cardbody"><h2>2. Your frozen payroll runs</h2><p class="sub">A Run ID identifies one payroll handoff. One-time email setup is reused. Repeating Sync for the same period updates the same run, never adds its claims again. Later approvals wait for the next run.</p><label class="field">Saved payroll run<select onchange="window.selectedRun=this.value;render()">${runs.map(r=>`<option value="${r.id}" ${selected?.id===r.id?'selected':''}>${esc(r.id)} · ${r.from} → ${r.to}</option>`).join('')||'<option>No payroll run prepared yet</option>'}</select></label>${selected?`<div class="notice"><strong>${esc(selected.id)}</strong> · ${selected.from} → ${selected.to}<br>Planned transfer ${selected.paymentDate} · Effective cutoff ${selected.cutoff}${selected.handoffAt?'<br>Payroll handoff recorded · '+esc(selected.handoffAt):''}</div>${problem?`<div class="notice amber">${esc(problem)} Resolve this in Payouts before exporting.</div>`:`<div class="scroll"><table><thead><tr><th>EMPLOYEE / EMAIL</th><th>THIS PERIOD CAD</th><th>LATE UNPAID CAD</th><th>ADD TO PAYROLL CAD</th><th>CLAIMS / STATUS</th></tr></thead><tbody>${totals.map(t=>`<tr><td>${esc(t.employee)}<small>${esc(t.email)}</small></td><td>${cad(t.periodCAD)}</td><td>${cad(t.lateCAD)}</td><td><strong>${cad(t.totalCAD)}</strong></td><td>${t.claims} · ${t.paid?'Paid':t.ready?'Reconciled':'Ready to generate'}</td></tr>`).join('')||'<tr><td colspan="5">No active claims remain in this run.</td></tr>'}</tbody></table></div><div class="flex" style="margin-top:16px"><button class="primary" onclick="exportPayrollRun()">Generate payroll CSV</button><button onclick="exportPayrollDetails()">Download claim breakdown</button><button onclick="syncPayrollRun()">Test sheet sync / retry</button><button onclick="payrollInstructions()">How to add this to salary payroll</button></div>`}`:'<p class="sub">Preview a period above, then prepare its exact claims.</p>'}</div></section><div class="grid"><section class="card"><div class="cardbody"><h2>3. Pick the easy handoff</h2><h3>Option A · CSV — works in this demo</h3><p class="sub">Generate payroll CSV. Import it into an Expense_Import tab in the existing salary workbook. One row contains each employee’s company email, period expenses, late expenses and final reimbursement CAD. Company email matches each employee automatically. Run ID prevents the same payroll handoff being added twice. Import by replacing this run’s rows, not appending a second copy.</p><h3>Option B · Google link — production setup</h3><p class="sub">Connect Google once. The portal can then create and reuse an expense-only spreadsheet automatically. The salary workbook imports the summary. Base salary stays in that workbook. The demo setup button below simulates creation only; it creates no Google file.</p><div class="flex"><button onclick="setupPayrollSheet()">Create export sheet · demo setup</button><button onclick="payrollInstructions()">Setup, formulas & rules</button></div><p class="sub">${s.syncSettings.provisionedDemo?'✓ Demo schema ready: Expense_Ledger, Payroll_Summary, Instructions. Google is not connected.':'No Google connection. No salary access.'}</p></div></section><section class="card"><div class="cardbody"><h2>Rules everyone can follow</h2><ol class="payroll-steps"><li><strong>Approval first.</strong> HR / Super Admin validates the bill and eligible amount.</li><li><strong>Choose period once.</strong> Use a fixed cycle; actual transfer date is separate.</li><li><strong>Review late claims.</strong> Older unpaid claims are labelled separately. Uncheck to defer them.</li><li><strong>Freeze, then export.</strong> Exact claims and CAD rates lock into this Run ID.</li><li><strong>Add once.</strong> Salary workbook calculates final pay; portal never stores base salaries.</li><li><strong>Confirm paid last.</strong> Open Payouts after successful transfer. Failed/uncertain transfers stay unpaid.</li></ol><button onclick="go('Payouts')">Open payment confirmation →</button><p class="sub">Google connection and transfers are simulated here. CSV files contain the real demo calculations.</p></div></section></div><details class="card"><summary class="cardbody">Advanced: individual batches, ledger, FX balances and sheet mapping</summary>${legacyLedger()}</details>`;}
function emailSetupCard(){return `<section class="card"><div class="cardbody"><div class="flex" style="justify-content:space-between"><div><h2>One-time payroll connection</h2><button onclick="openPayrollLab()">▶ Replay 3-month payroll demo</button><p class="sub">${s.payrollLink?`✓ Saved email mapping · ${s.payrollLink.emails.length} payroll emails · ${esc(s.payrollLink.mode)}`:'Set up once, then select a period and press Sync expenses.'}</p></div><button onclick="openEmailSetup()">${s.payrollLink?'Review connection':'Set up payroll emails once'}</button></div><p class="sub">Company email identifies the payroll row. Internal Employee ID protects history. Missing, duplicate or changed emails block the handoff. This browser-local demo does not connect Google or read base salaries.</p></div></section>`;}
function openEmailSetup(){if(!admin())return;modal(`<h2>One-time payroll email setup</h2><p class="sub">Production will read this list from the connected expense-only sheet. For this demo, paste only the company email column from payroll, one email per line. No salary figures or bank data.</p><form id="emailSetup"><label class="field">Payroll company emails<textarea name="emails" rows="8" required>${esc((s.payrollLink?.emails||[]).join('\n'))}</textarea></label><div class="flex" style="margin-top:16px"><button type="button" onclick="fillDemoEmails()">Use portal emails · fictional demo</button><button class="primary">Save connection once</button></div></form>`);$('#emailSetup').onsubmit=e=>{e.preventDefault();act(()=>{P.connectEmails(s,e.target.emails.value);closeModal();toast('Email mapping saved. Future periods reuse this setup.');})};}
function fillDemoEmails(){if(!admin())return;$('#emailSetup').emails.value=s.employees.map(e=>e.email).filter(Boolean).join('\n');}
function quickSyncPeriod(){if(!admin())return;try{payrollDraft=readPayrollPeriod();const result=P.autoSync(s,payrollDraft);window.selectedRun=result.runId;payrollPreview=null;save();toast(result.reused?'Same period updated safely. No duplicate claims; later approvals wait for the next period.':'Emails matched. Eligible expenses demo-synced; future periods exclude these reserved claims.');}catch(e){toast(e.message);}}
function readPayrollPeriod(){const f=$('#payrollPeriod');return {month:f.month.value,payDay:+f.payDay.value,from:f.from.value,to:f.to.value,paymentDate:f.paymentDate.value,employee:f.employee.value,includeLate:f.includeLate.checked};}
function applyPayCycle(){try{const d=readPayrollPeriod(),c=P.cycle(d.month+'-01',d.payDay);payrollDraft={...d,...c,paymentDate:c.scheduled};payrollPreview=null;render();}catch(e){toast(e.message);}}
function applyRolling(){try{const d=readPayrollPeriod();P.range({...d,from:d.paymentDate,to:d.paymentDate});payrollDraft={...d,from:new Date(Date.parse(d.paymentDate+'T00:00:00Z')-29*86400000).toISOString().slice(0,10),to:d.paymentDate};payrollPreview=null;render();}catch(e){toast(e.message);}}
function previewPeriod(e){e.preventDefault();if(!admin())return;try{payrollDraft=readPayrollPeriod();payrollPreview=P.preview(s,payrollDraft);payrollPreview.signature=P.fingerprint(payrollPreview);render();}catch(e){toast(e.message);}}
function periodPreviewHTML(p){return `<section class="card"><div class="cardbody"><h2>Review before adding to payroll</h2><div class="stats"><div class="stat"><small>IN PERIOD</small><strong>${p.periodCount}</strong></div><div class="stat"><small>LATE UNPAID</small><strong>${p.lateCount}</strong></div><div class="stat"><small>EXCLUDED</small><strong>${p.entries.length-p.selected.length}</strong></div><div class="stat featured"><small>ESTIMATED TOTAL CAD</small><strong>${cad(p.total)}</strong></div></div><p class="sub">Effective cutoff ${p.cutoff}. Any later expense stays available for a future run. Rates lock only when you prepare below.</p><div class="scroll"><table><thead><tr><th>CLAIM / EMPLOYEE</th><th>DATE</th><th>ORIGINAL / CAD</th><th>DECISION</th></tr></thead><tbody>${p.selected.map(x=>`<tr><td>${esc(x.claim.id)}<small>${esc(x.claim.employee)}</small></td><td>${esc(x.claim.date||'Not set')}</td><td>${esc(orig(x.claim))}<small>${cad(x.cad)}</small></td><td>${x.group==='excluded'?'Excluded':'✓ Included'}<small>${esc(x.reason)}</small></td></tr>`).join('')||'<tr><td colspan="4">No claims in this workspace. Submit and approve an expense first.</td></tr>'}</tbody></table></div><details style="margin-top:16px"><summary>Why ${p.entries.length-p.selected.length} claims are excluded</summary>${p.entries.filter(x=>x.group==='excluded').map(x=>`<div class="metricline"><span>${esc(x.claim.id)} · ${esc(x.claim.employee)}<small>${esc(x.claim.date||'No date')}</small></span><strong>${esc(x.reason)}</strong></div>`).join('')}</details><div class="formactions"><button class="primary" onclick="preparePayrollRun()" ${p.ids.length?'':'disabled'}>Prepare ${p.ids.length} claims & lock CAD</button></div></div></section>`;}
function preparePayrollRun(){if(!admin()||!payrollPreview)return;act(()=>{const now=readPayrollPeriod(),prior=payrollPreview.options;if(['from','to','paymentDate','employee','includeLate'].some(k=>now[k]!==prior[k]))throw Error('Period choices changed. Preview them again before preparing.');const run=P.createRun(s,payrollPreview.options,payrollPreview.ids,payrollPreview.signature);window.selectedRun=run.id;payrollPreview=null;toast('Payroll run prepared. Exact claims and rates are locked.');});}
function syncPayrollRun(){if(!admin())return;act(()=>{P.checkLink(s,s.payrollRuns.find(r=>r.id===window.selectedRun));P.syncRun(s,window.selectedRun);toast('Demo rows reconciled. No Google file was changed.');});}
function exportPayrollRun(){if(!admin())return;try{P.checkLink(s,s.payrollRuns.find(r=>r.id===window.selectedRun));P.syncRun(s,window.selectedRun);const rows=P.summary(s,window.selectedRun);if(!rows.length||rows.some(r=>!r.ready))throw Error('Resolve the run before exporting.');const run=s.payrollRuns.find(r=>r.id===window.selectedRun);run.handoffAt||=new Date().toISOString();E.log(s,actor(),'Generated payroll CSV '+run.id+'; not payment');save();csvDownload('Payroll_Summary-'+run.id+'.csv',['Run ID','Company Email','Employee','Period From','Period To','Period Expenses CAD','Late Unpaid CAD','Reimbursement CAD','Claim Count','Export Status','Employee ID'],rows.map(r=>[r.runId,r.email,r.employee,r.from,r.to,r.periodCAD,r.lateCAD,r.totalCAD,r.claims,'READY',r.employeeId]));toast('CSV generated. Add this Run ID once; confirm payment separately.');}catch(e){toast(e.message);}}
function exportPayrollDetails(){if(!admin())return;try{const rows=P.runRows(s,window.selectedRun);csvDownload('Expense_Detail-'+window.selectedRun+'.csv',['Run ID','Batch ID','Claim ID','Company Email','Employee ID','Employee','Expense Date','Category','Period From','Period To','Allocation','Original Amount','Currency','Approved Original','Locked CAD Rate','Reimbursement CAD','Payment Status'],rows.map(r=>{const c=s.claims.find(c=>c.id===r.claim);return[r.runId,r.batch,r.claim,r.email,r.employeeId,r.employee,c.date,c.category,r.from,r.to,r.group,r.original,r.currency,r.approved,r.rate,r.cad,r.paymentStatus];}));}catch(e){toast(e.message);}}
function setupPayrollSheet(){if(!admin())return;act(()=>{s.syncSettings.provisionedDemo=true;E.log(s,actor(),'Prepared demo export-sheet schema; Google not connected');toast('Demo setup ready. No Google spreadsheet has been created.');});payrollInstructions();}
function payrollInstructions(){if(!admin())return;modal(`<h2>Payroll handoff · simple setup</h2><p><strong>One-time email setup + repeat period sync.</strong> The saved mapping is reused. In this prototype, sheet writes are simulated; CSV is the working handoff.</p><ol><li>One-time setup: save the payroll company-email list (no salaries). Thereafter choose period → Sync expenses. The demo matches emails, freezes eligible claims and upserts the same run automatically. Real Google writes require the production connector.</li><li>Generate payroll CSV. In the salary Google Sheet, File → Import → Upload → insert as a new tab; name it <strong>Expense_Import</strong>. On repeat, replace the existing import tab’s data rather than appending duplicates. Keep previous payroll runs in a separate history tab.</li><li>In your salary payroll row: A2 = selected Run ID, B2 = company email. Use the formula below for reimbursement CAD.</li><li>Keep a single selected Run ID per employee payroll row. Record it in a Payroll_History tab: column A = completed Run ID, column B = normalized company email copied from the export. The guarded formula below blocks a run already in that history. Pay date / month labels alone do not identify a payout.</li><li>Add reimbursement to base salary and other approved adjustments inside the salary workbook only.</li><li>After successful transfer, append Run ID + company email to Payroll_History and preserve the final pay values in the historical payroll record. Open portal Payouts and confirm each employee batch with actual date/reference. Do not log a failed or uncertain transfer as completed. Export is never proof of payment.</li></ol><p><strong>Safe lookup:</strong> requires exactly one matching READY row and no completed payroll history entry. A processed run returns ALREADY PROCESSED. Duplicate imports or no match return CHECK IMPORT instead of silently doubling expenses.</p><pre class="payload">=IF(COUNTIFS(Payroll_History!A:A,A2,Payroll_History!B:B,LOWER(TRIM(B2)))>0,"ALREADY PROCESSED",IF(COUNTIFS(Expense_Import!A:A,A2,Expense_Import!B:B,LOWER(TRIM(B2)),Expense_Import!J:J,"READY")=1,SUMIFS(Expense_Import!H:H,Expense_Import!A:A,A2,Expense_Import!B:B,LOWER(TRIM(B2)),Expense_Import!J:J,"READY"),"CHECK IMPORT"))</pre><p class="sub">CSV columns: A Run ID · B Company Email · C Employee · D/E period · F period CAD · G late unpaid CAD · H total reimbursement CAD · I claim count · J export status · K internal Employee ID (retained for history).</p><p><strong>Final pay example:</strong> A2 = Run ID, B2 = company email, C2 = base salary CAD, D2 = reimbursement result above, E2 = approved positive/negative adjustments. F2 calculates final pay:</p><pre class="payload">=IF(ISNUMBER(D2),ROUND(C2+D2+E2,2),"CHECK EXPENSES")</pre><h3>Optional automatic Google link</h3><p class="sub">Production: HR connects Google once → portal creates one expense-only spreadsheet with Expense_Ledger, Payroll_Summary and Instructions → stores its ID → later syncs update that same file by Run ID + company email / Claim ID. Retried setup reuses the file. The salary workbook owner uses IMPORTRANGE to import A:J into Expense_Import, then the same guarded formula. This demo only prepares the schema; no OAuth or Google writes are connected.</p><pre class="payload">=IMPORTRANGE("EXPENSE_ONLY_SHEET_URL","Payroll_Summary!A:J")</pre><p><strong>Exceptions:</strong> rejected / draft / unapproved / paid / already reserved / uncovered / missing proof = excluded. Earlier approved unpaid = separately labelled late claim if selected. A transfer on the 7th cannot include an expense on the 9th; the remaining claim stays unpaid for the next run. Paying on the 13th does not automatically extend the fixed period beyond the 9th.</p><p class="sub">After handing a run to payroll, do not cancel it until payroll confirms it will not pay it. An exported run’s reservations stay locked to prevent accidental double handoff.</p>`);}

let payrollLabResult=null,labMonth=0,labStage='synced';
function openPayrollLab(){if(!admin())return;try{payrollLabResult=ExpensePayrollLab.simulate();labMonth=0;labStage='synced';showPayrollLab();}catch(e){toast(e.message);}}
function showPayrollLab(){if(!admin()||!payrollLabResult)return;const m=payrollLabResult.months[labMonth];modal(`<div class="eyebrow">ISOLATED FICTIONAL PAYROLL · NOT REAL SALARY DATA</div><h2>Replay three months, start to finish</h2><p class="sub">This uses a separate simulated payroll workbook and isolated expense data. Your workspace claims are unchanged. All base salaries, adjustments, references and payments below are fictional. The same expense engine performs matching, reservation, reconciliation and payment tracking.</p><div class="formgrid"><label class="field">Example payroll month<select aria-label="Example payroll month" onchange="labMonth=+this.value;labStage='synced';showPayrollLab()">${payrollLabResult.months.map((x,i)=>`<option value="${i}" ${labMonth===i?'selected':''}>${x.month}</option>`).join('')}</select></label><div class="notice"><strong>${m.from} → ${m.to}</strong><br>Transfer ${m.paymentDate} · ${labMonth===0?'Early payment on 8th':labMonth===1?'Late payment on 12th':'Usual payment on 10th'}<br>${esc(m.runId)}</div></div><div class="flex" style="margin:18px 0"><button onclick="labStage='synced';showPayrollLab()">1 · Email sync</button><button onclick="labStage='payroll';showPayrollLab()">2 · Calculate payroll</button><button onclick="labStage='paid';showPayrollLab()">3 · Confirm fictional payment</button><button onclick="labStage='next';showPayrollLab()">4 · Check next period</button></div>${labStage==='synced'?`<h3>Matched expenses → payroll reimbursement</h3><p class="sub">One-time email connection is reused for all three months. Only approved unpaid claims enter each run. Totals reconcile before handoff.</p><div class="scroll"><table><thead><tr><th>COMPANY EMAIL</th><th>PERIOD CAD</th><th>LATE CAD</th><th>ADD CAD</th></tr></thead><tbody>${m.summary.map(r=>`<tr><td>${esc(r.email)}</td><td>${cad(r.periodCAD)}</td><td>${cad(r.lateCAD)}</td><td>${cad(r.totalCAD)}</td></tr>`).join('')}</tbody></table></div>`:labStage==='next'?`<h3>No expense paid twice</h3><p>Across three months: ${payrollLabResult.settlements.length} unique expense settlements. Each Claim ID is paid once. The pending, rejected and company-paid examples remain outside payroll.</p><p class="sub">The first transfer is September 8: a September 9 expense is deferred, then appears as Late unpaid in October. A bill dated August 5 is approved later and also enters October once. Paying October salary on the 12th does not automatically extend its expense period beyond the 9th.</p><div class="flex"><button onclick="labGuardTest('duplicate')">Test duplicate import</button><button onclick="labGuardTest('wrong')">Test wrong email</button><button onclick="labGuardTest('reused')">Test already processed run</button></div><div id="labGuard" class="notice" style="margin-top:14px">Choose a test to see the blocked result.</div>`:`<h3>${labStage==='paid'?'Confirmed payments · fictional':'Separate payroll workbook calculation'}</h3><p class="sub">Base salary + reimbursement + approved adjustments = final pay. The salary figures exist only in this isolated example, never in normal expense exports.</p><div class="scroll"><table><thead><tr><th>EMPLOYEE / EMAIL</th><th>BASE CAD · DEMO</th><th>EXPENSE CAD</th><th>ADJUSTMENTS CAD</th><th>FINAL CAD</th><th>STATUS</th></tr></thead><tbody>${m.payroll.map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.email)}</small></td><td>${cad(r.base)}</td><td>${cad(r.reimbursementCAD)}</td><td>${cad(r.adjustment)}</td><td><strong>${cad(r.finalCAD)}</strong></td><td>${labStage==='paid'?'Paid · fictional':'Ready for payment'}${labStage==='paid'?`<small>${r.paymentDate} · ${esc(r.reference)}</small>`:''}</td></tr>`).join('')}</tbody></table></div><div class="notice">Final payroll ${cad(m.totalCAD)} · Included reimbursement ${cad(m.reimbursementCAD)}. ${labStage==='paid'?'Payment records were created by the isolated simulation; no money was sent.':'Calculation shown before simulated payment confirmation.'}</div>`}<div class="formactions"><button onclick="downloadPayrollLab()">Download all 3 months · fictional payroll CSV</button><button onclick="closeModal()">Back to my workspace</button></div>`);}
function labGuardTest(kind){const rows=payrollLabResult.months[labMonth][kind];$('#labGuard').innerHTML=rows.map(r=>`<p><strong>${esc(r.email)}</strong> · ${esc(r.error||'Matched safely')}</p>`).join('');}
function downloadPayrollLab(){if(!admin()||!payrollLabResult)return;csvDownload('FICTIONAL-three-month-payroll.csv',['DEMO ONLY','Month','Run ID','Company Email','Employee','Expense Period From','Expense Period To','Base CAD','Period Expenses CAD','Late Unpaid CAD','Reimbursement CAD','Approved Adjustments CAD','Final Pay CAD','Actual Payment Date','Fictional Reference','Status'],payrollLabResult.months.flatMap(m=>m.payroll.map(r=>['FICTIONAL DATA',m.month,m.runId,r.email,r.name,m.from,m.to,r.base,r.periodCAD,r.lateCAD,r.reimbursementCAD,r.adjustment,r.finalCAD,r.paymentDate,r.reference,'Paid - fictional'])));}

function render(){if(embedded&&!hostContext){$('#content').innerHTML='<div class="notice">Connecting to your Bevy employee account…</div>';return;}$('#person').style.display='none';if(!embedded){let identity=$('#active-identity');if(!identity){identity=document.createElement('span');identity.id='active-identity';identity.className='pill';$('.roles').append(identity);}identity.textContent=admin()?actor():person();}$('#nav').innerHTML=pages.map((p,i)=>({p,i})).filter(({p})=>admin()||['Overview','My expenses'].includes(p)).map(({p,i})=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><b>${icons[i]}</b>${p==='Review queue'?'Approval inbox'+(inbox().length?' · '+inbox().length:''):p}</button>`).join('');$('#content').innerHTML=page==='Overview'?overview():page==='My expenses'?claimsView():page==='Review queue'?claimsView(true):page==='Payouts'?payouts():page==='Payroll sync'?ledger():controls();}$('#role').onchange=()=>{closeModal();page='Overview';render()};$('#person').onchange=()=>{closeModal();render()};window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{s=JSON.parse(e.newValue);closeModal();render();toast('Workspace updated. New requests are reflected in your inbox.')}catch{}}});render();

if(embedded){document.body.classList.add('embedded');window.addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='bevy-expense-context')return;const ctx=e.data;if(!['Employee','HR','Super Admin'].includes(ctx.role)||!ctx.employees?.some(p=>p.name===ctx.employee))return;hostContext=ctx;if(!s.hostInitialized)mapHostSeed();s.employees=ctx.employees;page='Overview';save();});parent.postMessage({type:'bevy-expense-ready'},location.origin);}

function addCategory(){if(!admin())return;modal(`<h2>Add an expense category</h2><p class="sub">Reuse a tested form type. HR final approval and bill attachment remain mandatory.</p><form id="categoryForm"><div class="formgrid"><label class="field">Category name<input required name="label" maxlength="60"></label><label class="field">Form type<select name="kind"><option value="meal">Meal / specific date</option><option value="subscription">Subscription / billing cycle</option><option value="travel">Travel / specific date</option><option value="purchase">Purchase / item and quantity</option><option value="training">Training / course</option><option value="other">Other / work purpose</option></select></label><label class="field full">Guidance<input required name="note"></label></div><div class="formactions"><button class="primary">Add category</button></div></form>`);$('#categoryForm').onsubmit=e=>{e.preventDefault();act(()=>{const f=e.target,name=f.label.value.trim();if(!name||!/^([\p{L}\p{N} /&()-]){1,60}$/u.test(name)||Object.hasOwn(s.rules,name)||['__proto__','constructor','prototype'].includes(name))throw Error('Use a unique category name with letters, numbers, spaces, /, &, parentheses or a dash.');s.categoryDefs[name]={kind:f.kind.value,version:1,note:f.note.value};s.rules[name]='HR';s.policies[name]={covered:true,limit:100,prior:false};E.log(s,actor(),'Added category '+name+' using '+f.kind.value+' schema');closeModal()})};}

function verifyOwner(id){if(!admin())return;const c=s.claims.find(x=>x.id===id);if(!c)return;modal(`<h2>Verify original owner</h2><p>Check the original bill and employee record. This sends the claim back for HR approval.</p><form id="ownerForm"><label>Original employee ID<select name="employeeId">${s.employees.filter(e=>e.name===c.employee).map(e=>`<option value="${esc(e.id)}">${esc(e.id)} · ${esc(e.email)}</option>`).join('')}</select></label><label>Evidence checked<textarea name="reason" required></textarea></label><button>Verify and request reapproval</button></form>`);$('#ownerForm').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));E.bindOwner(s,id,d.employeeId,role(),actor(),d.reason);save();closeModal();toast('Owner verified. HR reapproval required.');}catch(error){toast(error.message);}};}
